class Solution {
public:
    string gcdOfStrings(string str1, string str2) {
        if (str1 + str2 != str2 + str1) return "";
        int a = str1.size(), b = str2.size();
        while (b) {
            int t = a % b;
            a = b;
            b = t;
        }
        int g = a;
        return str1.substr(0, g);
    }
};
